const ph=K.t.ph, TAU=Math.PI*2, W=K.w, H=K.h, gy=H*0.9;
const cams=[[0.307,0.215,1],[0.263,0.255,-1],[0.285,0.36,1],[0.263,0.43,-1],[0.315,0.50,1],[0.262,0.57,-1],[0.292,0.65,1]];
c.save(); c.lineCap='butt';
cams.forEach((cm,i)=>{
  const x=cm[0]*W, y=cm[1]*H, d=cm[2], cyc=1+(i%2);
  const th=d*(0.42+0.34*Math.sin(TAU*(ph*cyc+i*0.137)));
  const L0=Math.min((gy-y)/Math.max(0.35,Math.cos(th)),H*0.9);
  const ex=x+Math.sin(th)*L0, ey=y+Math.cos(th)*L0, wd=0.075+0.02*Math.sin(TAU*(ph*2+i));
  const ax=x+Math.sin(th-wd)*L0, ay=y+Math.cos(th-wd)*L0, bx=x+Math.sin(th+wd)*L0, by=y+Math.cos(th+wd)*L0;
  c.fillStyle=K.col('primary'); c.globalAlpha=0.07; c.beginPath(); c.moveTo(x,y); c.lineTo(ax,ay); c.lineTo(bx,by); c.closePath(); c.fill();
  c.globalAlpha=0.9; c.strokeStyle=K.col('primary'); c.lineWidth=2.2; c.setLineDash([16,10]); c.lineDashOffset=-ph*26*cyc*2;
  c.beginPath(); c.moveTo(x,y); c.lineTo(ex,ey); c.stroke();
  c.globalAlpha=0.45; c.lineWidth=1.2; c.beginPath(); c.moveTo(x,y); c.lineTo(ax,ay); c.moveTo(x,y); c.lineTo(bx,by); c.stroke(); c.setLineDash([]);
  const r=26+10*Math.sin(TAU*(ph*cyc*2+i*0.3)); c.globalAlpha=0.9; c.lineWidth=2;
  c.beginPath(); c.ellipse(ex,ey,r*1.8,r*0.6,0,0,TAU); c.stroke(); c.globalAlpha=0.5; c.beginPath(); c.ellipse(ex,ey,r*3.1,r*1.05,0,0,TAU); c.stroke();
  c.globalAlpha=1; c.fillStyle=K.col('accent'); c.fillRect(ex-3,ey-3,6,6);
  const on=K.hash(i,Math.floor(K.t.n/(K.t.fps/3)))>0.3; c.globalAlpha=on?1:0.25; c.fillStyle=K.col('primary'); c.beginPath(); c.arc(x,y,6,0,TAU); c.fill();
  c.globalAlpha=0.9; c.font='600 15px monospace'; c.fillStyle=K.col('accent'); if(i%3===0) c.fillText('CAM'+String(i+1).padStart(2,'0')+'  IR '+(th*57.3).toFixed(1)+'°',ex+r*3.3,ey+5);
});
c.restore();

const ph=K.t.ph, TAU=Math.PI*2, W=K.w, H=K.h;
const x=W*0.5, y=H*0.46, th=0.5*Math.sin(TAU*ph), L0=H*0.55, wd=0.16;
c.save(); const g=c.createLinearGradient(x,y,x+Math.sin(th)*L0,y+Math.cos(th)*L0); g.addColorStop(0,K.col('accent')); g.addColorStop(1,K.col('bg'));
c.globalAlpha=0.22; c.fillStyle=g; c.beginPath(); c.moveTo(x,y); c.lineTo(x+Math.sin(th-wd)*L0,y+Math.cos(th-wd)*L0); c.lineTo(x+Math.sin(th+wd)*L0,y+Math.cos(th+wd)*L0); c.closePath(); c.fill();
c.globalAlpha=0.9; c.strokeStyle=K.col('accent'); c.lineWidth=2; c.setLineDash([22,12]); c.lineDashOffset=-ph*34*2;
c.beginPath(); c.ellipse(x+Math.sin(th)*L0,y+Math.cos(th)*L0,L0*0.18,L0*0.06,0,0,TAU); c.stroke(); c.setLineDash([]); c.restore();

const ph=K.t.ph, TAU=Math.PI*2, W=K.w, H=K.h;
const T=[[0.20,0.33,0],[0.55,0.22,1],[0.80,0.40,2],[0.42,0.62,3]];
c.save();
T.forEach((t,i)=>{
  const cx=t[0]*W, cy=t[1]*H, s=120+36*Math.sin(TAU*(ph*2+i*0.25)), k=s*0.28;
  const lock=0.5+0.5*Math.sin(TAU*(ph+i*0.25));
  c.strokeStyle=K.col(lock>0.6?'primary':'accent'); c.lineWidth=3; c.globalAlpha=1; c.beginPath();
  [[-1,-1],[1,-1],[-1,1],[1,1]].forEach(q=>{c.moveTo(cx+q[0]*s,cy+q[1]*s-q[1]*(-k)); c.lineTo(cx+q[0]*s,cy+q[1]*s); c.lineTo(cx+q[0]*s-q[0]*k,cy+q[1]*s);});
  c.stroke(); c.lineWidth=1.5; c.beginPath(); c.moveTo(cx-s*1.5,cy); c.lineTo(cx-s*0.35,cy); c.moveTo(cx+s*0.35,cy); c.lineTo(cx+s*1.5,cy); c.moveTo(cx,cy-s*1.5); c.lineTo(cx,cy-s*0.35); c.moveTo(cx,cy+s*0.35); c.lineTo(cx,cy+s*1.5); c.stroke();
  c.font='700 18px monospace'; c.fillStyle=K.col(lock>0.6?'primary':'accent'); c.fillText((lock>0.6?'TRAVADO  ':'RASTREANDO  ')+'ALVO '+String(i+1).padStart(2,'0'),cx-s,cy-s-14);
  c.font='500 14px monospace'; c.fillStyle=K.col('secondary'); c.fillText('ALT '+(40+i*17)+' M  VEL '+(18+i*6)+' KM/H  ID '+Math.floor(K.hash(i,7)*65535).toString(16).toUpperCase().padStart(4,'0'),cx-s,cy+s+26);
});
c.restore();

const ph=K.t.ph, TAU=Math.PI*2, W=K.w, H=K.h, N=10, names=['perfil1.png','perfil2.png','perfil3.png','perfil4.png','perfil5.png','perfil6.png'];
const CW=250, CH=330, G=14, TL=170/G;
c.save();
for(let i=0;i<N;i++){
  const lane=i%3, spd=1+(i%2), u=(((i/N)+ph*spd)%1+1)%1, x=-CW+u*(W+CW*2), y=H*(0.12+0.27*lane)+((i*37)%40);
  const blink=K.hash(i,Math.floor(K.t.n/(K.t.fps/4)))>0.22, hot=K.hash(i,99)>0.6;
  c.globalAlpha=blink?1:0.3; c.fillStyle=K.col('bg'); c.fillRect(x,y,CW,CH); c.strokeStyle=K.col(hot?'primary':'accent'); c.lineWidth=3; c.strokeRect(x,y,CW,CH);
  const ax=x+(CW-170)/2, ay=y+14, nm=names[i%6], im=K.img(nm);
  if(im){ c.imageSmoothingEnabled=true;
    for(let r=0;r<G;r++)for(let q=0;q<G;q++){ c.drawImage(im, q*im.w/G, r*im.h/G, im.w/G, im.h/G, ax+q*TL, ay+r*TL, TL+0.6, TL+0.6); }
  } else {
    for(let r=0;r<G;r++)for(let q=0;q<G;q++){ const hx=(q-(G-1)/2)/4.2, hy=(r-4.6)/4.6, head=hx*hx+hy*hy<1, sh=r>8&&Math.abs(q-(G-1)/2)<(r-6)*1.05;
      if(!(head||sh)) continue; const v=0.35+0.65*K.hash(i*31+q,r+Math.floor(K.t.n/(K.t.fps/2))*0); c.fillStyle=K.col(hot?'primary':'secondary'); c.globalAlpha=(blink?1:0.3)*(0.35+0.65*v); c.fillRect(ax+q*TL,ay+r*TL,TL+0.6,TL+0.6); }
    c.globalAlpha=blink?1:0.3; c.font='600 12px monospace'; c.fillStyle=K.col('secondary'); c.fillText('PERFIL SINTÉTICO · SEM IMAGEM',x+14,y+CH-46); }
  c.globalAlpha=blink?1:0.3; c.fillStyle=K.col(hot?'primary':'accent'); c.font='700 17px monospace';
  const id=Math.floor(K.hash(i,3)*16777215).toString(16).toUpperCase().padStart(6,'0');
  c.fillText('ID '+id,x+14,y+210); c.font='500 13px monospace'; c.fillStyle=K.col('secondary');
  c.fillText('LOC  '+(-23.5+K.hash(i,5)*0.2).toFixed(4),x+14,y+232); c.fillText('REG  '+Math.floor(K.hash(i,6)*9000+1000)+' EVENTOS',x+14,y+250);
  c.fillStyle=K.col(hot?'primary':'accent'); c.fillRect(x+14,y+264,CW-28,22); c.fillStyle=K.col('bg'); c.font='700 13px monospace'; c.fillText(hot?'DADOS EXPOSTOS':'MONITORADO',x+22,y+280);
  const bw=(CW-28)*(0.2+0.8*K.hash(i,8)); c.fillStyle=K.col('secondary'); c.fillRect(x+14,y+296,CW-28,4); c.fillStyle=K.col(hot?'primary':'accent'); c.fillRect(x+14,y+296,bw*(0.5+0.5*Math.sin(TAU*(ph*2+i*0.2))),4);
}
c.restore();

const W=K.w, H=K.h, TAU=Math.PI*2, ph=K.t.ph;
const B=[[0.70,0.07,0.27,0.28,'noticia1.png'],[0.70,0.37,0.27,0.28,'noticia2.png'],[0.70,0.67,0.27,0.28,'noticia3.png']];
c.save();
B.forEach((b,i)=>{
  const x=b[0]*W,y=b[1]*H,w=b[2]*W,h=b[3]*H, im=K.img(b[4]);
  c.fillStyle=K.col('bg'); c.fillRect(x,y,w,h);
  if(im){ const k=Math.max(w/im.w,h/im.h), sw=w/k, sh=h/k; c.drawImage(im,(im.w-sw)/2,(im.h-sh)/2,sw,sh,x,y,w,h); }
  else { c.strokeStyle=K.col('secondary'); c.lineWidth=1; c.globalAlpha=0.5; for(let k=-h;k<w;k+=26){ c.beginPath(); c.moveTo(x+Math.max(0,k),y+Math.max(0,-k)); c.lineTo(x+Math.min(w,k+h),y+Math.min(h,h-(w-k)+0)); c.stroke(); } c.globalAlpha=1;
    c.fillStyle=K.col('secondary'); c.font='700 22px monospace'; c.fillText('INSERIR PRINT '+(i+1)+' · '+b[4],x+18,y+h/2); c.font='500 15px monospace'; c.fillText('FONTE · VEÍCULO · DATA · LINK (conferir antes de exibir)',x+18,y+h/2+28); }
  c.strokeStyle=K.col('primary'); c.lineWidth=4; c.strokeRect(x,y,w,h);
  c.fillStyle=K.col('primary'); c.fillRect(x,y-26,170,26); c.fillStyle=K.col('bg'); c.font='700 15px monospace'; c.fillText('REGISTRO '+String(i+1).padStart(2,'0'),x+10,y-8);
  const sc=((ph*2+i*0.33)%1)*h; c.globalAlpha=0.55; c.fillStyle=K.col('primary'); c.fillRect(x,y+sc,w,3); c.globalAlpha=1;
});
c.restore();
